def run_order(tasks):
    order = []
    state = {}

    def visit(name):
        st = state.get(name, 0)
        if st == 1:
            raise ValueError(f"Cyclic dependency detected involving {name}")
        if st == 2:
            return

        state[name] = 1
        for dep in tasks[name]:
            visit(dep)
        state[name] = 2
        order.append(name)

    for name in tasks:
        visit(name)
    return order

